package com.hau.ai.application.service;import com.hau.ai.application.port.out.*;import com.hau.ai.domain.exception.*;import com.hau.ai.domain.model.*;import java.io.*;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class DocumentService{public static final Set<String> TYPES=Set.of("text/plain");private final StoragePort storage;private final DocumentRepository repo;private final Clock clock;private final long max;public DocumentService(StoragePort s,DocumentRepository r,Clock c,org.springframework.core.env.Environment e){storage=s;repo=r;clock=c;max=Long.parseLong(e.getProperty("ai.document.max-size-bytes","10485760"));}@Transactional public DocumentMetadata upload(UUID owner,String name,String type,long size,InputStream data){if(!TYPES.contains(type))throw new UnsupportedDocumentException("Unsupported content type: "+type);if(size<=0||size>max)throw new UnsupportedDocumentException("Document size is invalid");var f=storage.store(name,data);return repo.save(new DocumentMetadata(UUID.randomUUID(),owner,name,type,size,f.key(),f.checksum(),Instant.now(clock)));}@Transactional(readOnly=true)public DocumentMetadata get(UUID id,UUID user){var d=repo.findById(id).orElseThrow(()->new NotFoundException("Document not found"));if(!d.ownerId().equals(user))throw new NotFoundException("Document not found");return d;}}
